@Override protected Character convertToType(final Class<?> type, final Object value) throws Exception {
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Unsupported type: " + type);
    }
    if (value instanceof Character) {
        return (Character) value;
    } else if (value instanceof String) {
        String strValue = (String) value;
        if (strValue.length() == 1) {
            return strValue.charAt(0);
        } else {
            throw new IllegalArgumentException("String value must be a single character");
        }
    } else if (value instanceof Number) {
        return (char) ((Number) value).byteValue();
    } else {
        throw new IllegalArgumentException("Unsupported value type: " + value.getClass());
    }
}

