@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Ensure the resultMap is not null
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }

    // Construct a complete bipartite graph
    int n = resultMap.size();
    int m = n / 2;
    for (int i = 0; i < m; i++) {
        String label1 = "p" + i;
        V vertex1 = resultMap.getOrDefault(label1, null);
        if (vertex1 == null) {
            throw new IllegalStateException("Vertex for label " + label1 + " not found");
        }
        for (int j = m; j < n; j++) {
            String label2 = "q" + (j - m);
            V vertex2 = resultMap.getOrDefault(label2, null);
            if (vertex2 == null) {
                throw new IllegalStateException("Vertex for label " + label2 + " not found");
            }
            target.addEdge(vertex1, vertex2);
        }
    }
}

